const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const Q = readInt();
    const K = readInt();

    const A = new Float64Array(N + 1);
    for (let i = 1; i <= N; i++) {
        A[i] = readInt();
    }

    const D_list = new Int32Array(N + 1);
    const used = new Uint8Array(N + 1);
    for (let t = 1; t <= Q; t++) {
        const d = readInt();
        D_list[t] = d;
        used[d] = 1;
    }

    let ptr = Q + 1;
    for (let i = 1; i <= N; i++) {
        if (!used[i]) {
            D_list[ptr++] = i;
        }
    }

    // Preparar chaves u_i = A_i + i e v_i = A_i - i
    const u_val = new Float64Array(N + 1);
    const v_val = new Float64Array(N + 1);
    for (let i = 1; i <= N; i++) {
        u_val[i] = A[i] + i;
        v_val[i] = A[i] - i;
    }

    function buildIndex(valArray) {
        const p = new Int32Array(N);
        for (let i = 0; i < N; i++) p[i] = i + 1;

        p.sort((a, b) => {
            const diff = valArray[a] - valArray[b];
            if (diff !== 0) return diff;
            return a - b;
        });

        let distinct = 0;
        for (let i = 0; i < N; i++) {
            if (i === 0 || valArray[p[i]] !== valArray[p[i - 1]]) {
                distinct++;
            }
        }

        const keys = new Float64Array(distinct);
        const head = new Int32Array(distinct);
        const count = new Int32Array(distinct);
        const pos = new Int32Array(N);

        let k = -1;
        for (let i = 0; i < N; i++) {
            pos[i] = p[i];
            if (i === 0 || valArray[p[i]] !== valArray[p[i - 1]]) {
                k++;
                keys[k] = valArray[p[i]];
                head[k] = i;
                count[k] = 1;
            } else {
                count[k]++;
            }
        }

        return { keys, head, count, pos };
    }

    const U_idx = buildIndex(u_val);
    const V_idx = buildIndex(v_val);

    function countInRange(idxData, targetKey, minIdx, maxIdx) {
        if (minIdx > maxIdx) return 0;
        const keys = idxData.keys;
        let l = 0, r = keys.length - 1;
        let found = -1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            if (keys[mid] === targetKey) {
                found = mid;
                break;
            } else if (keys[mid] < targetKey) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        if (found === -1) return 0;

        const h = idxData.head[found];
        const len = idxData.count[found];
        const pos = idxData.pos;

        // lower_bound para minIdx em pos[h ... h + len - 1]
        let low = h, high = h + len - 1;
        let first = h + len;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (pos[mid] >= minIdx) {
                first = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        // upper_bound para maxIdx em pos[h ... h + len - 1]
        low = h; high = h + len - 1;
        let last = h - 1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (pos[mid] <= maxIdx) {
                last = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (first <= last) {
            return last - first + 1;
        }
        return 0;
    }

    // DSU reverso para encontrar [L, R] de cada desmoronamento
    const parent = new Int32Array(N + 2);
    const compL = new Int32Array(N + 2);
    const compR = new Int32Array(N + 2);
    const active = new Uint8Array(N + 2);

    function find(i) {
        let root = i;
        while (parent[root] > 0) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            const nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    function union(i, j) {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
            compL[rootI] = Math.min(compL[rootI], compL[rootJ]);
            compR[rootI] = Math.max(compR[rootI], compR[rootJ]);
            parent[rootJ] = rootI;
        }
    }

    const L_bound = new Int32Array(N + 1);
    const R_bound = new Int32Array(N + 1);

    for (let t = N; t >= 1; t--) {
        const d = D_list[t];
        let l = d;
        let r = d;
        if (active[d - 1]) {
            const leftRoot = find(d - 1);
            l = compL[leftRoot];
        }
        if (active[d + 1]) {
            const rightRoot = find(d + 1);
            r = compR[rightRoot];
        }

        L_bound[t] = l;
        R_bound[t] = r;

        compL[d] = l;
        compR[d] = r;
        active[d] = 1;

        if (active[d - 1]) union(d, d - 1);
        if (active[d + 1]) union(d, d + 1);
    }

    const cnt_t = new Array(N + 1);
    let totalInitial = 0n;

    for (let t = 1; t <= N; t++) {
        const D = D_list[t];
        const L = L_bound[t];
        const R = R_bound[t];

        let curCnt = 0n;

        // Parte 1: i in [L, D-1] e j = D
        if (L <= D - 1) {
            // Tipo 1: u_i = u_D - K, i in [max(L, D - K), D - 1]
            curCnt += BigInt(countInRange(U_idx, u_val[D] - K, Math.max(L, D - K), D - 1));
            // Tipo 2: v_i = v_D + K, i in [max(L, D - K + 1), D - 1]
            curCnt += BigInt(countInRange(V_idx, v_val[D] + K, Math.max(L, D - K + 1), D - 1));
        }

        // Parte 2: i = D e j in [D+1, R]
        if (D + 1 <= R) {
            // Tipo 1: u_j = u_D + K, j in [D + 1, min(R, D + K)]
            curCnt += BigInt(countInRange(U_idx, u_val[D] + K, D + 1, Math.min(R, D + K)));
            // Tipo 2: v_j = v_D - K, j in [D + 1, min(R, D + K - 1)]
            curCnt += BigInt(countInRange(V_idx, v_val[D] - K, D + 1, Math.min(R, D + K - 1)));
        }

        // Parte 3: i in [L, D-1] e j in [D+1, R]
        const lenL = D - L;
        const lenR = R - D;

        if (lenL > 0 && lenR > 0) {
            if (lenL <= lenR) {
                for (let i = L; i <= D - 1; i++) {
                    const maxJ1 = Math.min(R, i + K);
                    if (D + 1 <= maxJ1) {
                        curCnt += BigInt(countInRange(U_idx, u_val[i] + K, D + 1, maxJ1));
                    }
                    const maxJ2 = Math.min(R, i + K - 1);
                    if (D + 1 <= maxJ2) {
                        curCnt += BigInt(countInRange(V_idx, v_val[i] - K, D + 1, maxJ2));
                    }
                }
            } else {
                for (let j = D + 1; j <= R; j++) {
                    const minI1 = Math.max(L, j - K);
                    if (minI1 <= D - 1) {
                        curCnt += BigInt(countInRange(U_idx, u_val[j] - K, minI1, D - 1));
                    }
                    const minI2 = Math.max(L, j - K + 1);
                    if (minI2 <= D - 1) {
                        curCnt += BigInt(countInRange(V_idx, v_val[j] + K, minI2, D - 1));
                    }
                }
            }
        }

        cnt_t[t] = curCnt;
        totalInitial += curCnt;
    }

    const ans = new Array(Q + 1);
    ans[0] = totalInitial;
    let running = totalInitial;
    for (let t = 1; t <= Q; t++) {
        running -= cnt_t[t];
        ans[t] = running;
    }

    let out = '';
    for (let t = 0; t <= Q; t++) {
        out += ans[t].toString() + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

